"""One-shot. Applies this session's changes to honestygfymodel.

NOT A REPO FILE. Upload it to the repo root, run it, screenshot the
RESULT line, then delete it:

    python apply_session.py
    rm apply_session.py

WHAT IT DOES
  * rewrites 6 files and creates 3 (app/engines/espn_wnba.py,
    tests/test_espn_wnba.py, README.md)
  * deletes wnba_backfill.py and app/styles/.keep
  * pins the three probe workflows against requirements.txt

WHY IT WRITES WHOLE FILES INSTEAD OF PATCHING
A patch script that str-replaces can match zero times and still report
success -- that is the failure this repo already has a rule about. So
every target carries the sha256 of the version it was built from. If
your working tree differs from that, NOTHING is written and the script
says which file drifted. Commit or pull first; a clean tree at the
commit these were built from is the only state it will touch.

It re-hashes every file AFTER writing and prints PASS/FAIL per file.
"""
import base64
import hashlib
import os
import sys


def sha(path):
    with open(path, "rb") as fh:
        return hashlib.sha256(fh.read()).hexdigest()[:16]


def main():
    # ---- 1. PRE-FLIGHT. Nothing is written until every file checks out.
    drift = []
    for rel, before, _after, *_body in FILES:
        exists = os.path.exists(rel)
        if before is None and exists:
            drift.append(f"{rel} (expected new, already present)")
        elif before is not None and not exists:
            drift.append(f"{rel} (missing)")
        elif before is not None and sha(rel) != before:
            drift.append(f"{rel} (changed since this was built)")
    for rel, before in REMOVE:
        if os.path.exists(rel) and sha(rel) != before:
            drift.append(f"{rel} (changed; not deleting)")

    if drift:
        print("ABORT: working tree does not match. Nothing was written.")
        for d in drift:
            print("  drift:", d)
        print("RESULT: aborted, " + str(len(drift)) + " file(s) drifted")
        return 1

    # ---- 2. WRITE. Each file once, whole.
    for rel, _before, _after, *body in FILES:
        parent = os.path.dirname(rel)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(rel, "wb") as fh:
            fh.write(base64.b64decode("".join(body)))

    for rel, _before in REMOVE:
        if os.path.exists(rel):
            os.remove(rel)

    # ---- 3. VERIFY WHAT IS ON DISK, not what this script believes.
    failures = []
    for rel, _before, after, *_body in FILES:
        ok = os.path.exists(rel) and sha(rel) == after
        print(("PASS  " if ok else "FAIL  ") + rel)
        if not ok:
            failures.append(rel)
    for rel, _before in REMOVE:
        ok = not os.path.exists(rel)
        print(("PASS  " if ok else "FAIL  ") + rel + " removed")
        if not ok:
            failures.append(rel)

    # ---- 4. The claims, checked against the written bytes.
    grep = [
        ("Home: card heights reserved in markup",
         "app/views/Home.py", "def _card_rows(picks, board):", True),
        ("Home: dead stColumn CSS gone",
         "app/views/Home.py", "align-items: stretch", False),
        ("Home: explore dead end gone",
         "app/views/Home.py", "switch to {sport} above", False),
        ("WNBA view: no ESPN URL of its own",
         "app/views/WNBA.py", "site.api.espn.com", False),
        ("WNBA view: reads the shared engine",
         "app/views/WNBA.py", "from engines.espn_wnba import live_scores", True),
        ("pipeline: reads the shared engine",
         "wnba_precompute.py", "from engines.espn_wnba import", True),
        ("pipeline: no second mirror list",
         "wnba_precompute.py", "SCOREBOARD_SOURCES = [", False),
        ("engine: mirror chain present",
         "app/engines/espn_wnba.py", "SCOREBOARD_SOURCES = [", True),
    ]
    for label, rel, needle, want in grep:
        try:
            text = open(rel, encoding="utf-8").read()
        except OSError:
            ok = False
        else:
            ok = (needle in text) if want else (needle not in text)
        print(("PASS  " if ok else "FAIL  ") + label)
        if not ok:
            failures.append(label)

    print("RESULT:", "all checks passed" if not failures
          else "FAILED " + "; ".join(failures))
    return 1 if failures else 0


